    for (const g of getters(inbox, "veaOutbox")) await identity(`identity:VEA_INBOX:${g}`, "reporter", v("VEA_INBOX"), `${g}()`, [], decodeAddress, (got) => [sameAddress(got, v("VEA_OUTBOX")), v("VEA_OUTBOX")], "inbox -> outbox link");
    const ri = getters(inbox, "router"), ro = getters(outbox, "router");
    if (ri.length && ro.length && idOk.reporter && idOk.adapter) {
      try {
        const a = decodeAddress(await call("reporter", v("VEA_INBOX"), `${ri[0]}()`, []));
        const b = decodeAddress(await call("adapter", v("VEA_OUTBOX"), `${ro[0]}()`, []));
        if (sameAddress(a, b)) ok("identity:VEA:router", { router: a });
        else fail("identity:VEA:router", `inbox.${ri[0]}()=${a} but outbox.${ro[0]}()=${b}`);
      } catch (err) {
        fail("identity:VEA:router", err.message);
      }
    }
  }

  const level = Object.fromEntries(Object.entries(values).map(([k, x]) => [k, x.level]));
  const limitations = [];
  if (bridges.includes("debridge")) limitations.push("deBridge has no machine-readable registry: gate addresses are verified by bytecode and getChainId() plus a docs citation only.");
  limitations.push("Bytecode and identity getters prove the contracts behave like the expected ones; they do not prove source-code identity. Use the block explorer verification for that.");
  limitations.push("Fee/funding amounts, HEADER_STORAGE and LZ DVN addresses hardcoded in script/layerZero/*.s.sol are operator-set and not verified here.");
  return { status: failures.length ? "failed" : "passed", checks, failures, values, level, limitations };
}
