    adapter: fakeRpc(1514, { [`${A(2)}:${eid}`]: word(30364), [`${A(6)}:0x8b0bbc9b`]: addrWord(A(5)), [`${A(6)}:0x9ac0c6d2`]: word(42161), [`${A(6)}:0x39d1e4b0`]: addrWord(A(7)) }),
  };
