    trusted: { problems: [], expected: {} },
    rpcs: { reporter: fakeRpc(42161, { [`${A(3)}:0x3408e470`]: word(42161) }), adapter: fakeRpc(1514, { [`${A(3)}:0x3408e470`]: word(100000013) }) },
  });
  assert.ok(debridge.failures.some((f) => /citation:DEBRIDGE_ADAPTER_GATE_ADDRESS/.test(f)), "uncited value rejected");
  assert.ok(debridge.checks.some((c) => c.name === "identity:DEBRIDGE_REPORTER_GATE_ADDRESS" && c.ok));
  assert.equal(debridge.values.DEBRIDGE_REPORTER_GATE_ADDRESS.level, "citation");
});
