        res.end(JSON.stringify({ jsonrpc: "2.0", id, result }));
      });
    });
    srv.listen(0, "127.0.0.1", () => resolve({ srv, url: `http://127.0.0.1:${srv.address().port}/v1/apikey-secret` }));
  });
}

